const alloted = (token as { allotedArea?: unknown })?.allotedArea;
const assignedArea =
  Array.isArray(alloted) || typeof alloted === "string"
    ? (alloted as string[] | string)
    : undefined;

const searchOrigin: LatLng = { lat, lng };
const searchDestination: LatLng | null =
