  // Pre-fill the PIP form with next level data
  setNewPIP({
    pipLevel: nextLevel,
    startDate,
    endDate: endDateStr,
    concerns: concerns,
    notes: `Automatically issued after ${currentPip.pipLevel} PIP was not cleared.`,
