    .replace(/years?/gi, "(Y)")
    .replace(/months?/gi, "(M)")
    .replace(/days?/gi, "(D)")
    .replace(/\s+/g, "");

  const date = new Date(startDate);
  const month = date.toLocaleString("default", { month: "short" });

  return `${shortDuration} ${month}`;
