  newValue: string
) => {
  // keep previous snapshot
  const prev = [...queries];

  // optimistic update
  setQueries?.((q: IQuery[]) =>
    q.map((item: IQuery) =>
      item._id === _id ? { ...item, [key]: newValue } : item
    )
  );

  try {
    await axios.put(`/api/leads/updateData/${_id}`, {
      field: key,
      value: newValue,
    });
  } catch (error) {
    console.error("Update failed", error);
    // rollback if API fails
    setQueries?.(prev);
  }
};


